// [TEST ONLY] 夹具 host half（#266 生成产物，勿手改；源模板 = selftest/fixtures/templates/integrator）
import { createMultiHostUpdate } from 'dsh-plugin-update/batch'

export const name = 'dsh-plugin-update-fixture-b'
export const inject = ['webServer']
export const BUILD_TAG = 'host v0.0.2'
export const ROUTE = '/_dsh/selftest-fixture-b'
const BUILD_TAG_PHONE = 'dsh-plugin-update-fixture-b.buildTag'
export const HOST_BEHAVIOR = 't4-settlement:20261102T175925'
// 批量席位声明（变体版的 host 侧也能自证：我这一席负责哪些目标）。
export const TARGET_KEYS = 'b/c'

type Json = Record<string, unknown>
type PhoneHandler = (args?: Json) => Promise<unknown>

function readJsonBody(req: any): Promise<unknown> {
  return new Promise((resolve, reject) => {
    let text = ''
    req.on('data', (chunk: unknown) => { text += String(chunk) })
    req.on('end', () => { try { resolve(text ? JSON.parse(text) : null) } catch (error) { reject(error) } })
    req.on('error', (error: unknown) => { reject(error) })
  })
}

function writeJson(res: any, status: number, body: Json): void {
  res.statusCode = status
  res.setHeader('content-type', 'application/json; charset=utf-8')
  res.end(JSON.stringify(body))
}

function registryUrlOf(config: Json): string | undefined {
  const configured = (config as { registryUrl?: unknown }).registryUrl
  if (typeof configured === 'string' && configured.length > 0) return configured
  const fromEnv = process.env['DSH_SELFTEST_REGISTRY']
  return typeof fromEnv === 'string' && fromEnv.length > 0 ? fromEnv : undefined
}

/** 安装时限（毫秒）：显式配置优先，其次环境变量；非正数/非数字一律不传（产品缺省接管）。 */
function installTimeoutMsOf(config: Json): number | undefined {
  const configured = (config as { installTimeoutMs?: unknown }).installTimeoutMs
  if (typeof configured === 'number' && Number.isFinite(configured) && configured > 0) return configured
  const fromEnv = Number(process.env['DSH_SELFTEST_INSTALL_TIMEOUT_MS'])
  return Number.isFinite(fromEnv) && fromEnv > 0 ? fromEnv : undefined
}

export function apply(ctx: any, config: Json = {}): void {
  const registryUrl = registryUrlOf(config)
  const installTimeoutMs = installTimeoutMsOf(config)
  const deps: Json = { ctx, logCtx: null }
  const depsConfig: Json = {}
  if (registryUrl) depsConfig['registryUrl'] = registryUrl
  if (installTimeoutMs !== undefined) depsConfig['installTimeoutMs'] = installTimeoutMs
  if (Object.keys(depsConfig).length > 0) deps["config"] = depsConfig
  const multi = createMultiHostUpdate(deps as any, {
    prefix: 'fxb',
    selfKey: 'b',
    selfOrder: 'last',
    drain: false,
    targets: [
      { key: 'b', title: '夹具 B 本体', packageName: 'dsh-plugin-update-fixture-b', prefix: 'fxb-b' },
      { key: 'c', title: '夹具 C', packageName: 'dsh-plugin-update-fixture-c', prefix: 'fxb-c' },
    ],
  })
  const handlers: Record<string, PhoneHandler> = {}
  for (const phone of Object.keys(multi.handlers)) {
    handlers[phone] = multi.handlers[phone] as PhoneHandler
  }
  handlers[BUILD_TAG_PHONE] = async () => ({
    buildTag: BUILD_TAG,
    role: 'integrator',
    packageName: name,
    behavior: HOST_BEHAVIOR,
    targetKeys: TARGET_KEYS,
  })
  const bridge = async (req: any, res: any): Promise<void> => {
    if (req.method !== 'POST') { writeJson(res, 405, { ok: false, error: 'method-not-allowed' }); return }
    let body: Json | null = null
    try { body = (await readJsonBody(req)) as Json | null } catch (error) { writeJson(res, 400, { ok: false, error: 'bad-json' }); return }
    const phone = body && typeof body['phone'] === 'string' ? String(body['phone']) : ''
    const handler = handlers[phone]
    if (typeof handler !== 'function') { writeJson(res, 404, { ok: false, error: 'unknown-phone' }); return }
    const args = body && typeof body['args'] === 'object' && body['args'] !== null ? (body['args'] as Json) : {}
    try { writeJson(res, 200, { ok: true, reply: await handler(args) }) }
    catch (error) { writeJson(res, 200, { ok: false, error: String((error as any)?.message ?? error) }) }
  }
  ctx.effect(() => ctx.webServer.register({ kind: 'prefix', path: ROUTE, handler: bridge }), 'dsh-plugin-update-fixture-b: phone bridge')
}

// [TEST ONLY] 夹具 client half（#266 生成产物，勿手改；源模板 = selftest/fixtures/templates/integrator）
declare function require(id: string): any
declare const document: any
declare const exports: any

const React = require('react')
const { mountUpdateBatchPanel, mountHubProgressDock } = require('dsh-plugin-update/panel-batch')
const { mountUpdateBatchEntry } = require('dsh-plugin-update/entry-batch')

const PLUGIN_ID = 'dsh-plugin-update-fixture-b'
const PREFIX = 'fxb-b'
const BATCH_PREFIX = 'fxb'
const ROUTE = '/_dsh/selftest-fixture-b'
const BUILD_TAG_PHONE = 'dsh-plugin-update-fixture-b.buildTag'
const BUILD_TAG = 'client v0.0.2'
const CARD_TITLE = '夹具 B · 更新演示（批量新版）'
const FIXTURE_KEY = 'b'
const UI_MODE = 'batch'
const SEAT_LINE = 'T4 组 D 注入 20261102T175925'
const HOST_BEHAVIOR_TEXT = '宿主行为 t4-settlement:20261102T175925'
const HUB_DOCK = true

async function call(phone: string, args: any): Promise<any> {
  const response = await fetch(ROUTE, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ phone, args: args || {} }),
  })
  const body = await response.json().catch(() => null)
  if (!body || body.ok !== true) throw new Error((body && body.error) || 'fixture bridge failed')
  return body.reply
}

function FixtureCard() {
  const hostRef = React.useRef(null)
  const [hostTag, setHostTag] = React.useState('host ?')
  const [behavior, setBehavior] = React.useState(null)
  React.useEffect(() => {
    const element = hostRef.current
    if (!element) return undefined
    const entryHost = document.createElement('div')
    const panelHost = document.createElement('div')
    const dockHost = document.createElement('div')
    dockHost.setAttribute('data-fixture-dock', HUB_DOCK ? 'hub-dock' : 'none')
    element.append(entryHost, panelHost, dockHost)
    const entry = mountUpdateBatchEntry(entryHost, { prefix: BATCH_PREFIX, call, variant: 'button', openOn: 'always', autoCheck: 'never' })
    const panel = mountUpdateBatchPanel(panelHost, { prefix: BATCH_PREFIX, call, mode: 'embedded', autoCheck: false, pollMs: 2000 })
    const dock = HUB_DOCK ? mountHubProgressDock(dockHost, { prefix: BATCH_PREFIX, call, title: '更新进度', mountAs: 'inline', hideWhenIdle: false, pollMs: 1500 }) : null
    let alive = true
    call(BUILD_TAG_PHONE, {}).then((reply: any) => {
      if (alive && reply && typeof reply.buildTag === 'string') setHostTag(reply.buildTag)
      if (alive && reply && 'behavior' in reply) setBehavior(typeof reply.behavior === 'string' ? reply.behavior : null)
    }).catch(() => {})
    return () => {
      alive = false
      try { entry.unmount() } catch (error) {}
      try { panel.unmount() } catch (error) {}
      if (dock) { try { dock.unmount() } catch (error) {} }
      element.innerHTML = ''
    }
  }, [])
  const children = [
    React.createElement('div', { key: 'title', 'data-fixture-section': 'title', style: { fontSize: 12, fontWeight: 600, margin: '0 0 2px 2px' } }, CARD_TITLE),
    React.createElement('div', { key: 'build', 'data-fixture-build-tag': BUILD_TAG, style: { fontSize: 11, opacity: 0.7, margin: '0 0 2px 2px' } }, BUILD_TAG),
    React.createElement('div', { key: 'host', 'data-fixture-host-tag': hostTag, style: { fontSize: 11, opacity: 0.7, margin: '0 0 2px 2px' } }, hostTag),
    React.createElement('div', {
      key: 'seat',
      'data-fixture-seat-line': SEAT_LINE === null ? 'none' : SEAT_LINE,
      style: { fontSize: 11, opacity: 0.75, margin: '0 0 2px 2px' },
    }, SEAT_LINE === null ? '单席位集成方（无批量席位行）' : SEAT_LINE),
    React.createElement('div', {
      key: 'behavior',
      'data-fixture-behavior': behavior === null ? 'none' : behavior,
      'data-fixture-behavior-text': HOST_BEHAVIOR_TEXT,
      style: { fontSize: 11, opacity: 0.75, margin: '0 0 8px 2px' },
    }, HOST_BEHAVIOR_TEXT),
    React.createElement('div', { key: 'hostref', ref: hostRef }),
  ]
  return React.createElement('div', {
    className: 'dsh-fixture-card',
    'data-fixture': FIXTURE_KEY,
    'data-fixture-ui': UI_MODE,
    'data-build-tag': BUILD_TAG,
    style: { position: 'fixed', left: 16, top: 72, width: 520, zIndex: 2147483000, pointerEvents: 'auto', background: '#fffbe8', color: '#1f1a0a', border: '1px solid rgba(160,120,32,.45)', borderRadius: 12, boxShadow: '0 12px 40px rgba(0,0,0,.28)', padding: 10, maxHeight: '84vh', overflow: 'auto' },
  }, children)
}

function apply(ctx: any): void {
  ctx.slots.inject('shell.overlay', () => ctx.slots.register({
    name: 'shell.overlay',
    id: PLUGIN_ID + '-overlay',
    label: () => PLUGIN_ID,
  }, () => React.createElement(FixtureCard)))
}

const inject = ['slots']
exports.apply = apply
exports.inject = inject
